INSERT INTO articulos
(numero_articulo, capitulo, descripcion, multa_min_cuotas, multa_max_cuotas, categoria)
VALUES
('Art. 12 Fracc. I', 'Cap. III - De los vehículos', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Placas de circulación vigentes, expedidas por la autoridad competente; (circular con placas vencidas).', 5, 10, 'documentacion'),
('Art. 12 Fracc. I', 'Cap. III - De los vehículos', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Placas de circulación vigentes, expedidas por la autoridad competente; (circular sin placas).', 30, 50, 'documentacion'),
('Art. 12 Fracc. II', 'Cap. III - De los vehículos', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Permiso provisional vigente, sólo en el caso de no portar placas de circulación los vehículos de uso particular; únicamente cuando este sea expedido en otra Entidad Federativa o en el extranjero;', 10, 15, 'documentacion'),
('Art. 12 Fracc. III', 'Cap. III - De los vehículos', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Tarjeta de circulación vigente original. En su caso la copia cotejada vigente de la tarjeta de circulación emitida por la Autoridad Competente, será equivalente al original;', 10, 15, 'documentacion'),
('Art. 12 Fracc. IV', 'Cap. III - De los vehículos', 'Para que los vehículos automotores circulen dentro del Municipio deberán portar lo siguiente: Calcomanía de placas y refrendo vigente.', 2, 4, 'documentacion'),
('Art. 13', 'Cap. III - De los vehículos', 'Queda prohibido colocar a los vehículos dispositivos u objetos que se asemejen a placas de circulación nacionales o extranjeras, salvo los vehículos autorizados por la Autoridad Competente. Las placas deberán ser colocadas en los vehículos autorizados, y serán las que expidan las Autoridades correspondientes; en caso de falsificación de placas de circulación, el vehículo que las porte será retirado de la circulación dando vista de lo anterior al Ministerio Público.', 15, 20, 'documentacion'),
('Art. 15 Párr. 1º', 'Cap. III - De los vehículos', 'Las placas deberán conservarse siempre limpias, sin alteraciones, ni mutilaciones, debiendo colocarse una en la parte frontal exterior del vehículo en el área provista por el fabricante, y la otra en la parte posterior exterior del vehículo. Ambas placas deberán estar siempre visibles para que su lectura sea clara y sin confusión, debiendo estar fijas al vehículo. En caso de no existir un área provista por el fabricante para la colocación de la placa, ésta se colocará en el área central de la defensa posterior y frontal exterior, según sea el caso. (circular con placas en lugar indebido).', 7, 15, 'documentacion'),
('Art. 15 Párr. 1º', 'Cap. III - De los vehículos', 'Las placas deberán conservarse siempre limpias, sin alteraciones, ni mutilaciones, debiendo colocarse una en la parte frontal exterior del vehículo en el área provista por el fabricante, y la otra en la parte posterior exterior del vehículo. Ambas placas deberán estar siempre visibles para que su lectura sea clara y sin confusión, debiendo estar fijas al vehículo. En caso de no existir un área provista por el fabricante para la colocación de la placa, ésta se colocará en el área central de la defensa posterior y frontal exterior, según sea el caso. (Falta de visibilidad en placas).', 10, 15, 'documentacion'),
('Art. 15 Párr. 2º', 'Cap. III - De los vehículos', 'Además, deberán mantenerse en buen estado de conservación y libres de objetos distintivos, de rótulos, micas obscuras, sistemas anti-radares o detector de dispositivos tecnológicos, dobleces, porta placas luminosas, opaco o cualquier alteración que dificulte o impida su legibilidad. (Instalar o utilizar micas, antirradares o detectores de radares en los vehículos).', 30, 40, 'documentacion'),
('Art. 19', 'Cap. III - De los vehículos', 'Queda prohibido el uso de placas en vehículos diferentes para los que fueron expedidas. Para el caso en que se detecten las placas en vehículos distintos a los registrados, se procederá a recoger y retener los documentos, así como el vehículo, dando vista al Ministerio Público.', 30, 40, 'documentacion'),
('Art. 21', 'Cap. III - De los vehículos', 'Los propietarios de los vehículos están obligados a reportar en forma inmediata a la Autoridad Estatal competente, los siguientes movimientos o eventos sobre los vehículos: Cambio de propietario; Cambio de domicilio; Cambio de tipo de vehículo; Cambio de tipo de servicio; Robo total del vehículo; Incendio, destrucción, desuso o desarme; y Recuperación después de un robo.', 10, 15, 'documentacion'),
('Art. 23 Fracc. II', 'Cap. III - De los vehículos', 'Los vehículos de carga con peso bruto mayor de 3,500- tres mil quinientos kilogramos, y todos aquellos que presten algún servicio (recolección, entrega, grúas) deberán llevar en sus puertas las leyendas siguientes: Nombre, domicilio y teléfono de la Persona Física o Moral para atención al público;', 3, 10, 'transporte_carga'),
('Art. 24 Fracc. I', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LLANTAS.- Los vehículos de 4-cuatro o más ruedas, deberán traer una llanta de refacción, así como herramienta en buen estado para su cambio;', 5, 15, 'seguridad_vehicular'),
('Art. 24 Fracc. III', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES. - Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. 1. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces delanteras como mínimo con dos faros de circulación delanteros que emitan luz blanca, dotados de un mecanismo para cambio de intensidad; debiendo la luz baja iluminar un área no menor a 30-treinta metros y la luz alta un área no menor a 100-cien metros. En el tablero de control debe existir una señal luminosa que indique al conductor el uso de la luz alta; Luces indicadoras de frenado en la parte trasera que emitan luz roja y sean visibles desde una distancia considerable. Estas luces deberán encenderse y aumentar de intensidad en forma automática al aplicarse los frenos; Luces direccionales de destello intermitente. Las delanteras deberán ser de color ámbar y las traseras de color rojo o ámbar; Faros o cuartos y reflejantes que emitan y reflejen luz amarilla en la parte delantera y luz roja en la parte trasera; Luces de destello intermitente para estacionamiento de emergencia; debiendo ser las delanteras de color ámbar y las traseras de color rojo o ámbar; Luz blanca que ilumine la placa posterior (según fabricante); Luces indicadoras de reversa. Debiendo estar colocadas en la parte posterior y que emitan luz blanca al aplicar la reversa (según fabricante); Luces y/o reflejantes especiales según el tipo y dimensiones del vehículo. Para lo anterior, se aplicará lo establecido en el Reglamento de Tránsito para Carreteras Federales; Luz interior en el compartimiento de pasajeros. La cual sólo debe ser utilizada por intervalos cortos, evitando con ello la distracción del conductor o entorpecer su visibilidad hacia el exterior; y Luz que ilumine el tablero de control. 2. Los transportes escolares deberán contar en la parte superior del vehículo, con 2-dos luces que emitan al frente luz amarilla y atrás 2-dos luces que emitan luz roja; 3. Los vehículos destinados a la conservación y mantenimiento de la vía pública, las grúas y demás vehículos de auxilio vial deben utilizar torretas de color ámbar; 4. Los remolques y semirremolques deberán cumplir con lo marcado en los incisos b), c), d), e), f), g) del numeral 1; 5. Las motocicletas deberán contar con el equipo de luces siguiente: Al menos un faro delantero que emita luz blanca con dispositivo para el cambio de intensidad; Al menos un faro trasero que emita luz roja y que aumente de intensidad al aplicar los frenos; Luces direccionales iguales a las de los vehículos de cuatro o más ruedas, así como una luz iluminadora de placa; y Contar con espejos laterales por ambos lados. 6. Las bicicletas deberán contar con un faro o reflejante de color blanco en la parte delantera y un reflejante de color rojo en la parte posterior; y 7. Los vehículos de tracción animal deben contar al frente con 2-dos reflejantes de color blanco o ámbar y con 2-dos de color rojo en la parte de atrás. Estos deberán tener un tamaño mínimo de 5-cinco centímetros de diámetro en el caso de ser redondos o de 5-cinco centímetros por cada lado si tienen otra forma. Estos deberán estar situados en los extremos de la parte delantera y posterior. (Circular sin luces delanteras y/o traseras).', 15, 20, 'seguridad_vehicular'),
('Art. 24 Fracc. III', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES.- Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces delanteras como mínimo con dos faros de circulación delanteros que emitan luz blanca, dotados de un mecanismo para cambio de intensidad; debiendo la luz baja iluminar un área no menor a 30treinta metros y la luz alta un área no menor a 100-cien metros. En el tablero de control debe existir una señal luminosa que indique al conductor el uso de la luz alta;', 5, 10, 'seguridad_vehicular'),
('Art. 24 Fracc. III', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES.- Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4- cuatro o más ruedas deberán contar con: Luces indicadoras de frenado en la parte trasera que emitan luz roja y sean visibles desde una distancia considerable. Estas luces deberán encenderse y aumentar de intensidad en forma automática al aplicarse los frenos; (circular con una luz indicadora de frenado).', 3, 5, 'seguridad_vehicular'),
('Art. 24 Fracc. III', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES.- Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces indicadoras de frenado en la parte trasera que emitan luz roja y sean visibles desde una distancia considerable. Estas luces deberán encenderse y aumentar de intensidad en forma automática al aplicarse los frenos; (circular sin luces indicadoras de frenado).', 15, 20, 'seguridad_vehicular'),
('Art. 24 Fracc. III', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES.- Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces direccionales de destello intermitente. Las delanteras deberán ser de color ámbar y las traseras de color rojo o ámbar;', 10, 15, 'seguridad_vehicular'),
('Art. 24 Fracc. III', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES.- Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luz blanca que ilumine la placa posterior (según fabricante);', 3, 5, 'seguridad_vehicular'),
('Art. 24 Fracc. III', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes. LUCES Y REFLEJANTES.- Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. Los vehículos de motor de 4-cuatro o más ruedas deberán contar con: Luces indicadoras de reversa. Debiendo estar colocadas en la parte posterior y que emitan luz blanca al aplicar la reversa (según fabricante);', 10, 15, 'seguridad_vehicular'),
('Art. 24 Fracc. III', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: LUCES Y REFLEJANTES.- Las luces y reflejantes de los vehículos deben estar dispuestos en cantidad, calidad, color, tamaño y posición marcada en las especificaciones de fabricación del vehículo de que se trate. 1. Los vehículos de motor de 4- cuatro o más ruedas deberán contar con: Luces y/o reflejantes especiales según el tipo y dimensiones del vehículo. Para lo anterior, se aplicará lo establecido en el Reglamento de Tránsito para Carreteras Federales;', 10, 15, 'seguridad_vehicular'),
('Art. 24 Fracc. V', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: CINTURÓN DE SEGURIDAD.- Todos los vehículos automotores deberán contar con cinturón de seguridad adecuado según el fabricante y el modelo;', 12, 15, 'cinturon_seguridad'),
('Art. 24 Fracc. VI', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: TAPÓN O TAPA DEL TANQUE DEL COMBUSTIBLE.- Este deberá ser de diseño original o universal. Debe evitarse el uso de madera, estopa, tela, botes o cualquier dispositivo;', 3, 5, 'seguridad_vehicular'),
('Art. 24 Fracc. VIII', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: CRISTALES.- Todos los cristales de los vehículos automotores deberán estar en buenas condiciones, mantenerse limpios y libres de objetos o materiales que impidan o limiten la visibilidad del exterior al interior y a la inversa. Todos los vehículos automotores deberán estar provistos de un cristal parabrisas transparente, inastillable y sin fracturas. (Circular con parabrisas sin cristal, astillado o con fracturas).', 10, 20, 'seguridad_vehicular'),
('Art. 24 Fracc. VIII', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: CRISTALES.- Todos los cristales de los vehículos automotores deberán estar en buenas condiciones, mantenerse limpios y libres de objetos o materiales que impidan o limiten la visibilidad del exterior al interior y a la inversa. Todos los vehículos automotores deberán estar provistos de un cristal parabrisas transparente, inastillable y sin fracturas. (Circular con los cristales con objetos o materiales que impidan o limiten la visibilidad del exterior al interior y a la inversa, polarizados u opacos).', 70, 80, 'seguridad_vehicular'),
('Art. 24 Fracc. XI', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: EXTINGUIDOR DE INCENDIOS.- Todos los vehículos automotores deberán contar con un extinguidor de incendios en buen estado de funcionamiento, excepto las motocicletas;', 10, 15, 'seguridad_vehicular'),
('Art. 24 Fracc. XII', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: SISTEMA DE ESCAPE.- Todos los vehículos automotores deberán estar provistos de un sistema de escape para controlar la emisión de ruidos, gases y humos derivados del funcionamiento del motor. Este sistema deberá ajustarse a los siguientes requisitos: No deberá haber roturas o fugas en ninguno de sus componentes desde el motor hasta la salida; Ninguna parte de sus componentes deberá pasar a través del compartimento para los pasajeros; La salida del tubo de escape deberá estar colocada de manera que las emisiones de gases y humos salgan en un lugar más atrás del compartimento de pasajeros; sin que esta salida sobresalga más allá de la defensa posterior; Los vehículos de carga que utilizan combustible diésel, además de cumplir con lo establecido en los incisos anteriores, deberán tener la salida del tubo de escape por lo menos 15-quince centímetros más arriba de la parte superior de la carrocería; y Las motocicletas deberán contar con una protección en el sistema de escape, que impida el contacto directo del conductor o pasajero, para evitarles quemaduras. Es obligación de los conductores de vehículos evitar que estos emitan humos y gases contaminantes; el producir ostensiblemente contaminación al medio ambiente, será causa de infracción. El propietario contará con un término de 30-treinta días naturales para realizar lo conducente en su vehículo a fin de corregir la falla por la cual emita contaminantes, pudiendo circular durante dicho período sólo para conducirlo al taller mecánico para los efectos ya especificados. En caso de incumplimiento a lo dispuesto en este artículo, la multa será incrementada al doble de la impuesta y será retirado de la circulación. (Circular con mofle o sistema de escape ruidoso o defectuoso).', 10, 15, 'seguridad_vehicular'),
('Art. 24 Fracc. XII', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: SISTEMA DE ESCAPE.- Todos los vehículos automotores deberán estar provistos de un sistema de escape para controlar la emisión de ruidos, gases y humos derivados del funcionamiento del motor. Este sistema deberá ajustarse a los siguientes requisitos: No deberá haber roturas o fugas en ninguno de sus componentes desde el motor hasta la salida; Ninguna parte de sus componentes deberá pasar a través del compartimento para los pasajeros; La salida del tubo de escape deberá estar colocada de manera que las emisiones de gases y humos salgan en un lugar más atrás del compartimento de pasajeros; sin que esta salida sobresalga más allá de la defensa posterior; Los vehículos de carga que utilizan combustible diésel, además de cumplir con lo establecido en los incisos anteriores, deberán tener la salida del tubo de escape por lo menos 15-quince centímetros más arriba de la parte superior de la carrocería; y Las motocicletas deberán contar con una protección en el sistema de escape, que impida el contacto directo del conductor o pasajero, para evitarles quemaduras. Es obligación de los conductores de vehículos evitar que estos emitan humos y gases contaminantes; el producir ostensiblemente contaminación al medio ambiente, será causa de infracción. El propietario contará con un término de 30-treinta días naturales para realizar lo conducente en su vehículo a fin de corregir la falla por la cual emita contaminantes, pudiendo circular durante dicho período sólo para conducirlo al taller mecánico para los efectos ya especificados. En caso de incumplimiento a lo dispuesto en este artículo, la multa será incrementada al doble de la impuesta y será retirado de la circulación. (Expedir humo o ruido en excesivo).', 15, 20, 'seguridad_vehicular'),
('Art. 24 Fracc. XIV', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: PANTALONERAS O CUBRELLANTAS.- Los vehículos de plataforma, caja, remolque, quinta rueda o de cualquier otro tipo en el que las llantas posteriores no tengan concha en la parte superior; deberán contar con pantaloneras (zoqueteras);', 10, 15, 'seguridad_vehicular'),
('Art. 24 Fracc. XV', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: ESPEJOS RETROVISORES.- Todo vehículo automotor deberá contar con un espejo retrovisor en su interior y espejos retrovisores laterales en el exterior del vehículo. Estos deberán estar siempre limpios y sin roturas.', 3, 5, 'seguridad_vehicular'),
('Art. 24 Fracc. XVII', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: DISPOSITIVOS PARA REMOLQUES.- Todos los remolques deberán tener además del dispositivo de unión al vehículo automotor, 2-dos cadenas adecuadas al peso de cada remolque; debiendo ir una a cada lado del frente del remolque. Estas cadenas deberán unirse al vehículo automotor para evitar el desprendimiento total del remolque en caso de falla del dispositivo de unión;', 10, 20, 'seguridad_vehicular'),
('Art. 24 Fracc. XVIII', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: VEHÍCULOS DE TRANSPORTE ESCOLAR.- Los vehículos de transporte escolar deberán cumplir además con los siguientes requisitos: Ventanillas protegidas con malla metálica para evitar que los escolares saquen alguna parte de su cuerpo;', 20, 25, 'seguridad_vehicular'),
('Art. 24 Fracc. XVIII', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: VEHÍCULOS DE TRANSPORTE ESCOLAR.- Los vehículos de transporte escolar deberán cumplir además con los siguientes requisitos: Colores distintivos, ámbar con una franja blanca y leyendas en color negro;', 15, 20, 'seguridad_vehicular'),
('Art. 24 Fracc. XIX', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: VEHÍCULOS TRANSPORTADORES DE CARGA PELIGROSA. - Los vehículos transportadores de materiales explosivos, flamables, tóxicos o peligrosos de cualquier índole, deberán llevar en la parte posterior y en los lados las leyendas siguientes: PELIGRO, MATERIAL EXPLOSIVO, FLAMABLE, TÓXICO O PELIGROSO. Lo anterior, además de cumplir con lo que establece la Sección 5 del Capítulo III;', 25, 35, 'seguridad_vehicular'),
('Art. 24 Fracc. XX', 'Cap. III - De los vehículos', 'Todos los vehículos que transiten por la vía pública en el Municipio, deberán tener en buen estado los dispositivos siguientes: VEHÍCULOS CONDUCIDOS POR PERSONAS CON DISCAPACIDAD.- Los vehículos que sean conducidos por personas con discapacidad deberán contar con los dispositivos especiales para cada caso. Estos y los que transportan a personas con discapacidad deberán contar con placas expedidas por la Autoridad Competente en donde aparezca el emblema correspondiente, para que puedan hacer uso de los lugares exclusivos. Estos vehículos no podrán hacer uso de los lugares exclusivos cuando no sean conducidos por personas con discapacidad o bien cuando no transporten a éstos.', 3, 5, 'seguridad_vehicular'),
('Art. 25 Fracc. I', 'Cap. III - De los vehículos', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Faros encendidos o reflejantes de colores diferentes al blanco o ámbar en la parte delantera;', 10, 20, 'accesorios_prohibidos'),
('Art. 25 Fracc. II', 'Cap. III - De los vehículos', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Faros encendidos o reflejantes de colores diferentes al rojo o ámbar en la parte posterior; con excepción solamente de las luces de reversa y de placa;', 10, 20, 'accesorios_prohibidos'),
('Art. 25 Fracc. IV', 'Cap. III - De los vehículos', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Radios que utilicen la frecuencia de la Dependencia de Tránsito correspondiente o cualquier otro cuerpo de seguridad;', 20, 30, 'accesorios_prohibidos'),
('Art. 25 Fracc. VI', 'Cap. III - De los vehículos', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Sirena o aparatos que emitan sonidos semejantes a ella, torreta y/o luces estroboscópicas de cualquier color con excepción de los vehículos oficiales, de emergencia o especiales; (circular con sirena abierta los vehículos no autorizados).', 20, 25, 'accesorios_prohibidos'),
('Art. 25 Fracc. VI', 'Cap. III - De los vehículos', 'Queda prohibido que los vehículos que circulen en la vía pública porten los accesorios o artículos siguientes: Sirena o aparatos que emitan sonidos semejantes a ella, torreta y/o luces estroboscópicas de cualquier color con excepción de los vehículos oficiales, de emergencia o especiales; (utilizar luces estroboscópicas en vehículos no autorizados).', 20, 30, 'accesorios_prohibidos'),
('Art. 37', 'Cap. III - De los vehículos', 'Los vehículos de transporte de carga pesada deberán circular por las vías que forman parte de la red troncal, establecidas en el Anexo 1 del presente Reglamento, de forma obligatoria por los carriles establecidos para su circulación, siendo éstos los carriles derechos; a excepción de los ya señalizados.', 30, 50, 'transporte_carga'),
('Art. 39', 'Cap. III - De los vehículos', 'Los vehículos de transporte de carga pesada, no podrán circular por las vías limitadas, que forman parte de la red troncal de acuerdo al Anexo 2, en un horario de 06:30 a 09:30 hrs., además se tendrá la restricción de horario vespertino de las 18:00 a las 20:00 hrs. en las vías limitadas establecidas en el Anexo 3; en ambos casos las restricciones se aplicarán únicamente de lunes a viernes. Los vehículos de transporte de carga pesada que circulen en la red troncal con configuraciones vehiculares de hasta 4- cuatro ejes no serán sujetos a las restricciones contenidas en el párrafo anterior. Los vehículos de transporte de materiales, sustancias o residuos peligrosos a granel, que no tengan destino final el área metropolitana de Monterrey obligatoriamente deberán hacer uso de los libramientos periféricos. Para los casos en que se tenga como origen el área metropolitana de Monterrey, deberá sujetarse a las rutas que al efecto se establezcan, y sean acordadas por los Municipios, la Secretaría de Comunicaciones y Transportes, Protección Civil y la Industria.', 30, 50, 'transporte_carga'),
('Art. 40', 'Cap. III - De los vehículos', 'Son vías restringidas para la circulación de vehículos de transporte de carga pesada, aquellas que conforman el primer cuadro del Municipio, las calles y avenidas de fraccionamientos habitacionales, además de aquellas vías que no se contemplen en el Anexo 1.', 30, 50, 'transporte_carga'),
('Art. 42', 'Cap. III - De los vehículos', 'Los vehículos de transporte de carga pesada con tractor doblemente articulado, es decir con una configuración T-S-R (tracto camión- semirremolque-remolque), T-S-S (tracto camión- semiremolque- semiremolque) o C-R (camión-remolque), podrán circular por las vías que forman parte de la red troncal, a excepción de aquellas vueltas o retornos en los tramos de vías que por su diseño geométrico no permitan la circulación de estas unidades, mismas que estarán debidamente señalizadas.', 50, 100, 'transporte_carga'),
('Art. 43', 'Cap. III - De los vehículos', 'No contar con el Registro vigente, referido en el artículo 43 del presente Reglamento.', 40, 60, 'transporte_carga'),
('Art. 43', 'Cap. III - De los vehículos', 'No contar con el Registro referido en el artículo 43 del presente Reglamento.', 120, 180, 'transporte_carga'),
('Art. 47 Fracc. II', 'Cap. III - De los vehículos', 'Los conductores de los vehículos en movimiento que transporten carga, tienen prohibido lo siguiente: Transportar en vehículos abiertos, material que despida mal olor;', 20, 30, 'transporte_carga'),
('Art. 47 Fracc. III', 'Cap. III - De los vehículos', 'Los conductores de los vehículos en movimiento que transporten carga, tienen prohibido lo siguiente: Transportar en vehículos abiertos, cadáveres de animales;', 15, 20, 'transporte_carga'),
('Art. 47 Fracc. V', 'Cap. III - De los vehículos', 'Los conductores de los vehículos en movimiento que transporten carga, tienen prohibido lo siguiente: Obstruir uno o más carriles de circulación por caída parcial o total de la carga.', 50, 200, 'transporte_carga'),
('Art. 48 Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Acomodar la carga dentro de los límites laterales del vehículo y de forma que no obstruya su visibilidad;', 15, 20, 'transporte_carga'),
('Art. 48 Fracc. II', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Cubrir, mojar y sujetar al vehículo la carga que pueda esparcirse y sujetar debidamente los cables tensores, lonas y demás accesorios que sujeten la carga; (transportar carga que se esparza sin mojarla, sujetarla o cubrirla).', 20, 30, 'transporte_carga'),
('Art. 48 Fracc. II', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Cubrir, mojar y sujetar al vehículo la carga que pueda esparcirse y sujetar debidamente los cables tensores, lonas y demás accesorios que sujeten la carga; (transportar carga con cables, lonas, y accesorios sin estar debidamente sujetos).', 20, 30, 'transporte_carga'),
('Art. 48 Fracc. III', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Que el peso y dimensiones de la carga cumplan con la Norma Oficial Mexicana correspondiente;', 50, 100, 'transporte_carga'),
('Art. 48 Fracc. IV', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Proteger durante el día con banderolas rojas de un tamaño no menor a 50- cincuenta centímetros por lado la carga que sobresalga a la parte posterior del vehículo. De noche esta protección será con luces rojas visibles por lo menos desde 300- trescientos metros. En ningún caso la carga sobresaliente podrá tener longitud mayor a la cuarta parte de la longitud del vehículo. No se podrá transportar carga sobresaliente cuando las condiciones climatológicas dificulten la conducción; (transportar carga sobresaliente hacia atrás más de lo permitido).', 10, 15, 'transporte_carga'),
('Art. 48 Fracc. IV', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Proteger durante el día con banderolas rojas de un tamaño no menor a 50- cincuenta centímetros por lado la carga que sobresalga a la parte posterior del vehículo. De noche esta protección será con luces rojas visibles por lo menos desde 300- trescientos metros. En ningún caso la carga sobresaliente podrá tener longitud mayor a la cuarta parte de la longitud del vehículo. No se podrá transportar carga sobresaliente cuando las condiciones climatológicas dificulten la conducción; (transportar carga sobresaliente sin protección).', 10, 15, 'transporte_carga'),
('Art. 48 Fracc. V', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Portar la autorización correspondiente cuando transporte explosivos, material tóxico o materiales peligrosos. En este caso el vehículo deberá contar con las características adecuadas para transportar dicha carga; de acuerdo al Reglamento para el Transporte Terrestre de Materiales y Residuos Peligrosos;', 30, 50, 'transporte_carga'),
('Art. 48 Fracc. VI', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Abstenerse de utilizar personas para sujetar la carga y abstenerse de transportar carga que arrastre. (Transportar carga que arrastre o pueda caerse).', 15, 20, 'transporte_carga'),
('Art. 48 Fracc. VI', 'Cap. III - De los vehículos', 'Los conductores de vehículos de carga deberán cumplir lo siguiente: Abstenerse de utilizar personas para sujetar la carga y abstenerse de transportar carga que arrastre. (Utilizar personas para proteger o sujetar carga).', 15, 20, 'transporte_carga'),
('Art. 48 BIS Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos vocacionales destinados a la transportación de concreto premezclado, además de cualquier disposición aplicable de este Reglamento, deberán asegurar que el vehículo cumpla con lo siguiente: No derramar su carga o residuos de esta durante su circulación, maniobra, carga o descarga.', 50, 100, 'transporte_carga'),
('Art. 48 BIS', 'Cap. III - De los vehículos', 'Los conductores de vehículos vocacionales destinados a la transportación de concreto premezclado, además de cualquier disposición aplicable de este Reglamento, deberán asegurar que el vehículo cumpla con lo siguiente: Contar con tapa o sello hermético en la boca de carga.', 20, 30, 'transporte_carga'),
('Art. 48 BIS', 'Cap. III - De los vehículos', 'Los conductores de vehículos vocacionales destinados a la transportación de concreto premezclado, además de cualquier disposición aplicable de este Reglamento, deberán asegurar que el vehículo cumpla con lo siguiente: Circular con la canaleta de descarga replegada, asegurada y libre de residuos que puedan derramarse', 20, 30, 'transporte_carga'),
('Art. 48 BIS', 'Cap. III - De los vehículos', 'Los conductores de vehículos vocacionales destinados a la transportación de concreto premezclado, además de cualquier disposición aplicable de este Reglamento, deberán asegurar que el vehículo cumpla con lo siguiente: Contar con la palanca de control de giro de olla asegurada durante su circulación.', 20, 30, 'transporte_carga'),
('Art. 48 BIS Fracc. V', 'Cap. III - De los vehículos', 'Los conductores de vehículos vocacionales destinados a la transportación de concreto premezclado, además de cualquier disposición aplicable de este Reglamento, deberán asegurar que el vehículo cumpla con lo siguiente: Guardafangos o faldones que protejan las llantas de arrojar salpicaduras de concreto residual al pavimento u otros vehículos.', 20, 30, 'transporte_carga'),
('Art. 48 BIS', 'Cap. III - De los vehículos', 'Los conductores de vehículos vocacionales destinados a la transportación de concreto premezclado, además de cualquier disposición aplicable de este Reglamento, deberán asegurar que el vehículo cumpla con lo siguiente: Asegurar que el volumen de carga de concreto esté limitado para que en las pendientes no se provoque el derrame de concreto.', 30, 60, 'transporte_carga'),
('Art. 49 Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Acatar todas las disposiciones dictadas por el personal Municipal designado para la vigilancia del tránsito y de los promotores voluntarios de seguridad vial autorizados por la Secretaría. En casos de emergencia o de siniestros, deberán acatar también cualquier disposición de los miembros de los cuerpos de seguridad, auxilio o rescate; (no respetar indicaciones de promotores voluntarios).', 5, 10, 'obligaciones_conductor'),
('Art. 49 Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Acatar todas las disposiciones dictadas por el personal Municipal designado para la vigilancia del tránsito y de los promotores voluntarios de seguridad vial autorizados por la Secretaría. En casos de emergencia o de siniestros, deberán acatar también cualquier disposición de los miembros de los cuerpos de seguridad, auxilio o rescate; (no respetar indicaciones del Policía de Tránsito).', 25, 50, 'obligaciones_conductor'),
('Art. 49 Fracc. II', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Circular con las puertas de sus vehículos cerradas;', 15, 20, 'obligaciones_conductor'),
('Art. 49 Fracc. IV', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Utilizar el cinturón de seguridad y hacer que los pasajeros hagan lo mismo. Para el caso de menores de 7-siete años, se ajustará a lo ordenado por el Artículo 50 del presente Reglamento;', 12, 15, 'cinturon_seguridad'),
('Art. 49 Fracc. V', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Ascender y descender pasajeros a una distancia no mayor de 50-cincuenta centímetros de la banqueta o acotamiento;', 20, 30, 'obligaciones_conductor'),
('Art. 49 Fracc. VI', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Ceder el paso a los invidentes y personas con discapacidad en cualquier lugar y respetar los “Exclusivos” para éstos en áreas públicas y/o privadas con acceso al público;', 20, 30, 'peatones'),
('Art. 49 Fracc. VII', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Ceder el paso a los peatones que en zonas de cruce permitidas que se encuentren sobre los carriles de circulación o hayan iniciado el cruce de éstos;', 10, 15, 'peatones'),
('Art. 49 Fracc. VIII', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Ceder el paso a los peatones cuando se tenga que atravesar la banqueta, al entrar o salir de cocheras o estacionamientos;', 10, 15, 'peatones'),
('Art. 49 Fracc. IX', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Hacer alto en cruce de vía férrea; (no respetar paso de vehículos sobre rieles).', 20, 30, 'obligaciones_conductor'),
('Art. 49 Fracc. IX', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Hacer alto en cruce de vía férrea; (no hacer alto en la vía de ferrocarril).', 20, 30, 'obligaciones_conductor'),
('Art. 49 Fracc. X', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Utilizar solamente un carril a la vez;', 15, 20, 'obligaciones_conductor'),
('Art. 49 Fracc. XII', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Usar anteojos o cualquier dispositivo cuando así lo tenga indicado por prescripción médica como necesarios para conducir vehículos;', 5, 10, 'obligaciones_conductor'),
('Art. 49 Fracc. XIII', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Entregar al personal designado de la Autoridad Municipal su licencia de conducir, la tarjeta de circulación del vehículo y póliza de seguro vigente cuando se le soliciten. En caso de hechos de tránsito y/o infracción, los documentos serán retenidos por el Policía de Tránsito sólo si las placas del vehículo no son expedidas por la Autoridad Competente en el Estado de Nuevo León;', 10, 15, 'licencia_conducir'),
('Art. 49 Fracc. XV', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Iniciar la marcha con precaución y gradualmente, cediendo el paso a los vehículos que estando en movimiento, estén rebasando al vehículo detenido para adelantarlo y también a los vehículos en movimiento en forma transversal al vehículo detenido; si esto ocurre en un crucero o intersección;', 15, 20, 'obligaciones_conductor'),
('Art. 49 Fracc. XVI', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Someterse a un examen para determinar los grados de alcohol en la sangre o su equivalente en cualquier otro sistema de medición, o bien, para detectar la influencia de drogas o estupefacientes, cuando le sea requerido por el personal autorizado del Municipio;', 50, 200, 'ebriedad'),
('Art. 49 Fracc. XVIII', 'Cap. III - De los vehículos', 'Los conductores de vehículos deberán cumplir con lo siguiente: Reducir la velocidad ante cualquier concentración de peatones y/o vehículos.', 15, 20, 'velocidad'),
('Art. 50 Anexo 5', 'Cap. III - De los vehículos', 'Los conductores de automóviles que viajen con pasajeros menores de 7- siete años de edad, deberán asegurarse que éstos ocupen una de las plazas traseras sobre la hilera inmediatamente posterior a los asientos del conductor o del copiloto que cuente con cinturón de seguridad de tres puntos. Los menores de 7-siete años deberán ser transportados en un Sistema de Retención Infantil o asiento elevador debidamente colocado, que cumpla con certificación estandarizada, con un sistema de anclaje adecuado y que se ajuste a las características indicadas en el Anexo 5 de este Reglamento. Únicamente si el vehículo no cuenta con asiento trasero, los menores de 7-siete años podrán viajar en el asiento delantero, siempre y cuando cuenten con espacio suficiente para instalar un Sistema de Retención Infantil acordes a su peso o talla y se desactive el sistema de bolsas de aire.', 15, 20, 'seguridad_infantil'),
('Art. 51 Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo o estado de ebriedad incompleto, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. La Autoridad Municipal determinará los medios que se utilizarán para la detección de estos casos; (conducir bajo efectos de medicamentos que alteren las facultades).', 30, 200, 'ebriedad'),
('Art. 51 Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo o estado de ebriedad incompleto, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. La Autoridad Municipal determinará los medios que se utilizarán para la detección de estos casos; (conducir bajo el influjo de drogas o sustancias toxicas).', 50, 200, 'ebriedad'),
('Art. 51 Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo o estado de ebriedad incompleto, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. La Autoridad Municipal determinará los medios que se utilizarán para la detección de estos casos; (conducir en estado de ebriedad incompleto o en estado de ebriedad completo).', 50, 200, 'ebriedad'),
('Art. 51 Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo o estado de ebriedad incompleto, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. La Autoridad Municipal determinará los medios que se utilizarán para la detección de estos casos; (conducir en estado de ebriedad incompleta o en estado de ebriedad completa y cometer cualquier infracción del presente reglamento).', 100, 300, 'ebriedad'),
('Art. 51 Fracc. I', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir en estado de ebriedad completo o estado de ebriedad incompleto, así como cuando sus facultades físicas o mentales se encuentren alteradas por el influjo de drogas, estupefacientes o medicamentos. La Autoridad Municipal determinará los medios que se utilizarán para la detección de estos casos; (conducir en estado de ebriedad incompleta o en estado de ebriedad completa en forma reincidente).', 200, 600, 'ebriedad'),
('Art. 51 Fracc. II', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Sujetar, con una o ambas manos, aparatos de telecomunicación, teléfonos celulares, radios o cualquier aparato electrónico u objeto de las nuevas tecnologías de la información y comunicación, que puedan distraer al conductor al momento de conducir un vehículo. Se exceptúa de lo anterior, a los conductores de las unidades de seguridad, de conformidad con lo establecido en la Ley de Seguridad Pública para el Estado de Nuevo León; así como a las unidades de asistencia médica, protección civil, bomberos y de emergencias, dada la naturaleza de sus funciones;', 20, 30, 'distracciones'),
('Art. 51 Fracc. III', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Entorpecer la circulación de vehículos;', 15, 20, 'prohibiciones_conductores'),
('Art. 51 Fracc. IV', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Transportar personas en el exterior del vehículo o en lugar no especificado para el transporte de pasajeros;', 5, 15, 'prohibiciones_conductores'),
('Art. 51 Fracc. V', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Entorpecer la marcha de desfiles o manifestaciones permitidas, cortejos fúnebres o eventos deportivos autorizados en la vía pública;', 10, 15, 'prohibiciones_conductores'),
('Art. 51 Fracc. VI', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Efectuar competencias de cualquier tipo con sus vehículos sin autorización de la Autoridad Municipal;', 20, 50, 'prohibiciones_conductores'),
('Art. 51 Fracc. VII', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Llevar consigo aparatos que hagan uso de la frecuencia de radio de la Autoridad Municipal u otro cuerpo de seguridad;', 20, 30, 'prohibiciones_conductores'),
('Art. 51 Fracc. VIII', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Utilizar equipos de sonido de tal forma que su volumen sea molesto para el ciudadano o pasajeros en caso de transporte de servicio público.', 10, 15, 'ruido'),
('Art. 51 Fracc. IX', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Utilizar audífonos con excepción de aquellos aparatos que cuenten con un solo auricular;', 10, 15, 'distracciones'),
('Art. 51 Fracc. X', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Ascenso o descenso de pasaje sobre el segundo carril de circulación;', 20, 30, 'prohibiciones_conductores'),
('Art. 51 Fracc. XI', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular a los lados, adelante o atrás de vehículos de emergencia que estén haciendo uso de su sirena o de torretas de luz roja, azul, blanca o ámbar;', 20, 30, 'prohibiciones_conductores'),
('Art. 51 Fracc. XII', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular sobre las mangueras de bomberos o de protección civil, banquetas o zonas exclusivas para uso de peatones, parques públicos, camellones, barreras que dividan carriles de circulación opuesta o canalicen carriles de movimiento específico de circulación, barreras o dispositivos para la protección de obras u obstáculos en la vía pública y sus marcas de aproximación;', 8, 20, 'prohibiciones_conductores'),
('Art. 51 Fracc. XIII', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular en sentido contrario, a menos que así lo indique la Autoridad facultada, o bien, los señalamientos o dispositivos viales;', 15, 20, 'reglas_circulacion'),
('Art. 51 Fracc. XIV', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular con vehículos o encender sus motores cuando éstos expidan humo o ruidos excesivos;', 15, 20, 'prohibiciones_conductores'),
('Art. 51 Fracc. XV', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Permitir a terceros el uso de dispositivos de control y manejo del vehículo en movimiento;', 10, 15, 'prohibiciones_conductores'),
('Art. 51 Fracc. XVI', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Circular por los carriles exclusivos para el transporte confinado; exceptuando cualquier tipo de vehículo de emergencia;', 50, 200, 'transporte_publico'),
('Art. 51 Fracc. XVII', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Empalmarse con otro vehículo o rebasarlo utilizando un mismo carril de circulación, o hacer uso de más de un carril a la vez;', 10, 15, 'rebase'),
('Art. 51 Fracc. XVIII', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Transportar pasajeros en estado de ebriedad o bajo el influjo de alguna droga o enervante, en autobuses y camiones de pasajeros de servicio público de transporte;', 5, 10, 'ebriedad'),
('Art. 51 Fracc. XIX', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Transportar animales sin los dispositivos adecuados de sujeción, entendiéndose por estos correas o pecheras con adaptador especial para el cinturón de seguridad, cajas transportadoras, barreras que imposibiliten el acceso del animal al asiento del conductor, entre otros, de acuerdo a lo previsto en el ANEXO 6 del presente Reglamento de los Dispositivos de Protección Animal. Cuando el animal viaje en las cajas de las camionetas tipo pick up, los animales invariablemente deberán ir dentro de cajas transportadoras de tamaño adecuado para cada animal, mismas que a su vez deben ir sujetas de manera firme al interior de la caja;', 10, 15, 'prohibiciones_conductores'),
('Art. 51 Fracc. XX', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir con personas, animales u objetos que obstruyan o limiten las maniobras de manejo;', 5, 10, 'prohibiciones_conductores'),
('Art. 51 Fracc. XXI', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Remolcar vehículos si no se cuenta con el equipo especial para ello;', 10, 15, 'prohibiciones_conductores'),
('Art. 51 Fracc. XXII', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Transportar más de dos pasajeros en el asiento delantero de cualquier tipo de vehículo, en caso de ser asiento individual. Se permite sólo un pasajero en cada asiento; se prohíbe que un pasajero viaje encima de otro. La cantidad de pasajeros lo determinará el fabricante, excluyéndose los vehículos modificados;', 10, 15, 'motocicletas'),
('Art. 51 Fracc. XXV', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Manifestar una conducta evidente de hostigamiento hacia otros conductores haciendo mal uso del vehículo que conduce;', 15, 20, 'ebriedad'),
('Art. 51 Fracc. XXVI', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Conducir el vehículo con un aparato de televisión encendido, ubicado en el tablero, asiento delantero o adherido al vehículo, de manera que el conductor del mismo pueda observar la pantalla del aparato televisivo; así como sostener el conductor, pasajero o acompañante el aparato de televisión encendido, de manera que el conductor pueda observar la pantalla del mismo;', 15, 20, 'distracciones'),
('Art. 51 Fracc. XXVII', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Poseer, en el área de pasajeros de un vehículo, una botella, lata u otro envase que contenga una bebida alcohólica que haya sido abierta o que tenga los sellos rotos o el contenido parcialmente consumido; no se considerará como área de pasajeros aquella con asientos habilitados para carga;', 50, 200, 'ebriedad'),
('Art. 51', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Permitir la suplantación como conductor por otra persona, en un hecho de tránsito;', 50, 200, 'licencia_conducir'),
('Art. 51 Fracc. XXIX', 'Cap. III - De los vehículos', 'Los conductores de vehículos tienen prohibido lo siguiente: Permitir el ascenso y descenso de pasajeros en lugares no autorizados para los vehículos del servicio público Local o Federal de pasajeros;', 20, 30, 'transporte_publico'),
('Art. 52', 'Cap. III - De los vehículos', 'La velocidad máxima en el Municipio es de 50-cincuenta kilómetros por hora, excepto en los lugares en los que se especifique mediante el señalamiento respectivo una velocidad diferente. En el caso de que el exceso de velocidad sea captado a través de dispositivos tecnológicos, se observará lo siguiente: a) Cuando el exceso de velocidad se encuentre dentro de los 11 a los 20 kilómetros por encima de lo establecido en el señalamiento respectivo. b) Cuando el exceso de velocidad se encuentre dentro de los 21 a los 31 kilómetros por encima de lo establecido en el señalamiento respectivo. c) Cuando el exceso de velocidad sea de 32 kilómetros en adelante, por encima de lo establecido en el señalamiento respectivo.', 5, 15, 'velocidad'),
('Art. 52 Fracc. I', 'Cap. III - De los vehículos', 'La velocidad máxima en el Municipio es de 50-cincuenta kilómetros por hora, excepto en los lugares en los que se especifique mediante el señalamiento respectivo una velocidad diferente. No obstante, lo anterior, se establece lo siguiente: La velocidad máxima es de 30-treinta kilómetros por hora en zonas y horarios escolares, dichos horarios serán de 7:00 a 9:30, de 11:30 a 14:30 y 16:30 a 18:30 horas, en días hábiles escolares;', 20, 30, 'velocidad'),
('Art. 53 Fracc. I', 'Cap. III - De los vehículos', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: Usar casco protector el conductor y en su caso su acompañante, así como portar lentes u otros protectores oculares;', 15, 20, 'casco'),
('Art. 53 Fracc. II', 'Cap. III - De los vehículos', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: No efectuar piruetas o zigzaguear;', 20, 40, 'motocicletas'),
('Art. 53 Fracc. III', 'Cap. III - De los vehículos', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: No remolcar o empujar otro vehículo;', 10, 15, 'motocicletas'),
('Art. 53 Fracc. IV', 'Cap. III - De los vehículos', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: No sujetarse a vehículos en movimiento;', 13, 20, 'motocicletas'),
('Art. 53 Fracc. V', 'Cap. III - De los vehículos', 'Además de lo que les corresponda en lo hasta aquí establecido, los motociclistas deberán cumplir con lo siguiente: No rebasar a ningún vehículo de motor por el mismo carril, a excepción de aquellos que pertenezcan a Policía o Tránsito en el cumplimiento de su trabajo;', 10, 15, 'motocicletas'),
('Art. 54', 'Cap. III - De los vehículos', 'Queda estrictamente prohibido circular por los carriles exclusivos para e l transporte confinado.', 20, 50, 'transporte_publico'),
('Art. 55', 'Cap. III - De los vehículos', 'Cuando un vehículo esté indebidamente estacionado, cause interrupción a la circulación u obstruya la visibilidad de señales o dispositivos de tránsito, será retirado con grúa y se depositará en el lote autorizado, si la interrupción de la circulación es intencional, se hará acreedor a una sanción sin derecho a descuento ni cancelación. Los gastos de acarreo y pensión serán por cuenta del infractor.', 25, 35, 'estacionamiento'),
('Art. 57', 'Cap. III - De los vehículos', 'Cuando por circunstancias ajenas al conductor, el vehículo se encuentre sobre un carril de circulación y le sea imposible el movimiento del vehículo, se deberán de colocar inmediatamente los siguientes dispositivos: DE DÍA: Dos banderolas de color rojo de tamaño no menor a 50-cincuenta centímetros por lado, o reflejantes del mismo color; DE NOCHE: Linternas, luces o reflejantes, también de color rojo. Estos dispositivos deben colocarse a 10-diez metros y 50-cincuenta metros hacia cada lado de donde se aproximen vehículos, de tal forma que sean visibles desde una distancia de 100- cien metros.', 10, 20, 'reglas_circulacion'),
('Art. 67', 'Cap. III - De los vehículos', 'Queda prohibido separar lugares de estacionamiento si el lugar no está autorizado como exclusivo. El personal de la Dependencia correspondiente deberá retirar cualquier dispositivo utilizado con el propósito anterior.', 10, 15, 'estacionamiento'),
('Art. 68', 'Cap. III - De los vehículos', 'Queda prohibido el estacionamiento en áreas habitacionales y vía pública a aquellos vehículos o combinación de éstos con longitud mayor a 6.50 seis metros con cincuenta centímetros, a menos que estén realizando maniobras de carga y descarga o que se cuente con permiso especial expedido por la Autoridad Municipal, la cual podrá cancelar el permiso por razones de vialidad.', 20, 30, 'estacionamiento'),
('Art. 69', 'Cap. III - De los vehículos', 'Queda prohibido el estacionamiento en la vía pública de remolques y semirremolques, si no están unidos o acoplados a los vehículos que los estiran.', 15, 20, 'estacionamiento'),
('Art. 71', 'Cap. III - De los vehículos', 'Las empresas de cualquier tipo que posean flotillas de vehículos deben tener un área de su propiedad para estacionarlos sin afectar a sus vecinos. Por lo tanto, no podrán estacionar sus vehículos frente a domicilios contiguos a su domicilio social o centro de operaciones.', 30, 50, 'estacionamiento'),
('Art. 72', 'Cap. III - De los vehículos', 'Se prohíbe estacionar vehículos: Sobre banquetas, isletas, camellones o áreas diseñadas para separación de carriles, rotondas, zonas peatonales o diseñados para uso exclusivo de peatones y sobre y alrededor de parques públicos; Dentro de intersecciones y en cualquier área diseñada solamente para la circulación de vehículos; En las esquinas u ochavos; A una distancia menor a un metro de las zonas de cruce de peatones, pintadas o imaginarias; A una distancia menor a un metro o mayor de 1.50-un metro con cincuenta centímetros del límite de propiedad cuando no haya banqueta; En un área comprendida desde 50- cincuenta metros antes y hasta 50- cincuenta metros después de puentes, túneles, vados, lomas, pasos a desnivel para vehículos, curvas y en cualquier otro lugar donde la visibilidad del vehículo estacionado no sea posible desde 100-cien metros; Frente a hidrantes, rampas de carga y descarga o de acceso para personas con discapacidad o cocheras; En la acera derecha, en las calles cuya circulación sea de un solo sentido; En carriles principales cuando haya carriles secundarios; En zonas de carga y descarga sin estar realizando estas maniobras; A menos de 10-diez metros a cada lado de una señal de parada obligatoria para camiones de pasajeros, debiendo dejar un espacio mínimo de 10-diez metros; A menos de 5-cinco metros o sobre vías de ferrocarril; En cualquier forma que obstruya a los conductores la visibilidad de semáforos, señales de ALTO y de CEDA EL PASO, o cualquier otra señal de vialidad; En donde lo prohíba una señal o Policía de Tránsito, o en lugares exclusivos, sin permiso del titular; En calles con amplitud menor a 5-cinco metros, a excepción de motocicletas, bicicletas y bicimotos; A un lado de rotondas, camellones o isletas; En línea con la banqueta en donde el estacionamiento se haga en forma diagonal o viceversa; En cajones de estacionamiento para uso exclusivo de personas con discapacidad, a menos que se trate de un vehículo que esté debidamente identificado y que cuente con el permiso vigente y que transporte a la persona con discapacidad; En cajones de estacionamiento donde existan estacionómetros instalados por la autoridad correspondiente, sin que se cubra el monto respectivo para utilizarlo; En las guarniciones o cordones donde exista pintura color amarillo, rojo o azul en una o ambas caras; igualmente se prohíbe estacionar vehículos en las esquinas, aunque no exista señalamiento de no estacionarse, debiéndose respetar una distancia en ellas de 5-cinco metros lineales en ambos sentidos de las calles convergentes; y Estacionarse arriba de guías táctiles, pues obstaculizarían la movilidad de las personas con discapacidad visual.', 10, 15, 'estacionamiento'),
('Art. 72 Fracc. I', 'Cap. III - De los vehículos', 'Se prohíbe estacionar vehículos: Sobre banquetas, isletas, camellones o áreas diseñadas para separación de carriles, rotondas, zonas peatonales o diseñados para uso exclusivo de peatones y sobre y alrededor de parques públicos;', 10, 20, 'estacionamiento'),
('Art. 72 Fracc. II', 'Cap. III - De los vehículos', 'Se prohíbe estacionar vehículos: Dentro de intersecciones y en cualquier área diseñada solamente para la circulación de vehículos;', 10, 15, 'estacionamiento'),
('Art. 72 Fracc. VII', 'Cap. III - De los vehículos', 'Se prohíbe estacionar vehículos: Frente a hidrantes, rampas de carga y descarga o de acceso para personas con discapacidad o cocheras;', 30, 50, 'estacionamiento'),
('Art. 72 Fracc. XIV', 'Cap. III - De los vehículos', 'Se prohíbe estacionar vehículos: En donde lo prohíba una señal o Policía de Tránsito, o en lugares exclusivos, sin permiso del titular;', 15, 20, 'estacionamiento'),
('Art. 72 Fracc. XVIII', 'Cap. III - De los vehículos', 'Se prohíbe estacionar vehículos: En cajones de estacionamiento para uso exclusivo de personas con discapacidad, a menos que se trate de un vehículo que esté debidamente identificado y que cuente con el permiso vigente y que transporte a la persona con discapacidad;', 30, 50, 'estacionamiento'),
('Art. 72 Fracc. XIX', 'Cap. III - De los vehículos', 'Se prohíbe estacionar vehículos: En cajones de estacionamiento donde existan estacionómetros instalados por la autoridad correspondiente, sin que se cubra el monto respectivo para utilizarlo;', 1, 2, 'estacionamiento'),
('Art. 72', 'Cap. III - De los vehículos', 'Se prohíbe estacionar vehículos: En las esquinas u ochavos; A una distancia menor a un metro de las zonas de cruce de peatones, pintadas o imaginarias; A una distancia menor a un metro o mayor de 1.50-un metro con cincuenta centímetros del límite de propiedad cuando no haya banqueta; En un área comprendida desde 50- cincuenta metros antes y hasta 50- cincuenta metros después de puentes, túneles, vados, lomas, pasos a desnivel para vehículos, curvas y en cualquier otro lugar donde la visibilidad del vehículo estacionado no sea posible desde 100-cien metros; En la acera derecha, en las calles cuya circulación sea de un solo sentido; En carriles principales cuando haya carriles secundarios; En zonas de carga y descarga sin estar realizando estas maniobras; A menos de 10-diez metros a cada lado de una señal de parada obligatoria para camiones de pasajeros, debiendo dejar un espacio mínimo de 10-diez metros; A menos de 5-cinco metros o sobre vías de ferrocarril; En cualquier forma que obstruya a los conductores la visibilidad de semáforos, señales de ALTO y de CEDA EL PASO, o cualquier otra señal de vialidad; En calles con amplitud menor a 5-cinco metros, a excepción de motocicletas, bicicletas y bicimotos; A un lado de rotondas, camellones o isletas; En línea con la banqueta en donde el estacionamiento se haga en forma diagonal o viceversa; En las guarniciones o cordones donde exista pintura color amarillo, rojo o azul en una o ambas caras; igualmente se prohíbe estacionar vehículos en las esquinas, aunque no exista señalamiento de no estacionarse, debiéndose respetar una distancia en ellas de 5-cinco metros lineales en ambos sentidos de las calles convergentes; y Estacionarse arriba de guías táctiles, pues obstaculizarían la movilidad de las personas con discapacidad visual.', 10, 20, 'estacionamiento'),
('Art. 73 Párr. 2º', 'Cap. III - De los vehículos', 'Los conductores de unidades de transporte escolar están obligados a encender sus luces especiales cuando se detengan para el ascenso y/o descenso de escolares y no deberán hacerlo en ninguna otra circunstancia.', 15, 20, 'transporte_escolar'),
('Art. 75', 'Cap. III - De los vehículos', 'Los pasajeros y ocupantes de vehículos, según el caso, deberán cumplir con lo siguiente: Usar el cinturón de seguridad; Viajar debidamente sentados en el lugar que les corresponda; Descender siempre por el lado de la banqueta o acotamiento; Los pasajeros del Servicio Local o Federal deben tener para los demás pasajeros y éstos para el operador una conducta de respeto, absteniéndose de realizar cualquier acto que ocasione molestias. Ningún pasajero puede hacer uso de aparatos reproductores de sonido a menos que use audífonos; y, Usar debidamente casco protector al viajar en motocicleta. (Faltas diversas por conductores del servicio público del transporte).', 20, 30, 'cinturon_seguridad'),
('Art. 75', 'Cap. III - De los vehículos', 'Los pasajeros y ocupantes de vehículos, según el caso, deberán cumplir con lo siguiente: Usar el cinturón de seguridad; Viajar debidamente sentados en el lugar que les corresponda; Descender siempre por el lado de la banqueta o acotamiento; Los pasajeros del Servicio Local o Federal deben tener para los demás pasajeros y éstos para el operador una conducta de respeto, absteniéndose de realizar cualquier acto que ocasione molestias. Ningún pasajero puede hacer uso de aparatos reproductores de sonido a menos que use audífonos; y, Usar debidamente casco protector al viajar en motocicleta. (Faltas diversas cometidas por pasajeros y ocupantes de vehículos).', 20, 30, 'cinturon_seguridad'),
('Art. 76', 'Cap. III - De los vehículos', 'Los pasajeros y ocupantes de vehículos, tienen prohibido lo siguiente: Ingerir bebidas alcohólicas en vehículos; Sacar del vehículo parte de su cuerpo u objetos; Arrojar basura u objetos a la vía pública; Abrir las puertas de vehículos en movimiento; Abrir sin precaución las puertas de vehículos estacionados hacia el lado de la circulación; Descender de vehículos en movimiento; Sujetarse del conductor o distraerlo; Operar los dispositivos de control del vehículo; Interferir en las funciones de los Policías de Tránsito; y, Viajar en lugares destinados para carga o fuera del vehículo. El propietario del vehículo será el responsable solidario de las infracciones en que incurran los ocupantes. (Faltas diversas cometidas por pasajeros y ocupantes de vehículos).', 20, 30, 'ebriedad'),
('Art. 76 Fracc. III', 'Cap. III - De los vehículos', 'Los pasajeros y ocupantes de vehículos, tienen prohibido lo siguiente: Arrojar basura u objetos a la vía pública.', 70, 90, 'basura_residuos'),
('Art. 76 Fracc. IX', 'Cap. III - De los vehículos', 'Los pasajeros y ocupantes de vehículos, tienen prohibido lo siguiente: Interferir en las funciones de los Policías de Tránsito;', 5, 10, 'reglas_circulacion'),
('Art. 80', 'Cap. III - De los vehículos', 'En cruceros donde converjan dos o más avenidas, calles o carreteras, la prioridad de paso se determinará como sigue: En las esquinas o lugares donde haya señal gráfica de ALTO, los conductores deberán detener completamente sus vehículos. Esto es, antes de las zonas de peatones marcadas o a seis metros antes de la esquina en caso de que no estén marcadas; antes de iniciar la marcha de sus vehículos, los conductores deberán ceder el paso a los peatones que estén cruzando o hayan iniciado el cruce de una calle o avenida. Posteriormente, sin invadir el carril de circulación de la calle transversal, deberán cerciorarse de que no se aproxima ningún vehículo con el que se pueda ocasionar algún hecho de tránsito y hasta entonces iniciarán la marcha, evitando detenerse dentro de la intersección; Cuando todas las calles o carreteras convergentes en un crucero tengan señal de ALTO, la prioridad de paso será como sigue: Todos los vehículos deben hacer ALTO al llegar al cruce, el derecho de paso lo tiene el primero en llegar. Si solo uno hace ALTO y otro(s) no, el derecho de paso es de quien haya hecho ALTO. En las esquinas o lugares donde exista señal gráfica de CEDA EL PASO, los conductores podrán entrar a la intersección si por la calle transversal no se aproxima ningún vehículo que constituya peligro de hecho de tránsito; en caso contrario deberán cederle el paso; En cruceros o intersecciones donde no existan señales gráficas de ALTO o CEDA EL PASO, no haya semáforos funcionando normalmente y no se encuentre un Policía de Tránsito dirigiendo la circulación; tendrán prioridad de paso: Las avenidas sobre las calles; La calle o avenida que tenga mayor cantidad de carriles de circulación; En intersecciones en forma de “T”, la que atraviese sobre la que entronca; La calle pavimentada sobre la no- pavimentada; y En las rotondas donde la circulación no esté controlada por señales o semáforos, los conductores que vayan a incorporarse a la misma deberán ceder el paso a los vehículos que ya se encuentren en ella. Al no presentarse las condiciones marcadas en los incisos anteriores, al conductor de un vehículo al que se le presente otro entrando a un crucero o aproximándose al suyo sobre su lado derecho, deberá cederle el paso.', 10, 15, 'prioridad_paso'),
('Art. 80 Fracc. I', 'Cap. III - De los vehículos', 'En cruceros donde converjan dos o más avenidas, calles o carreteras, la prioridad de paso se determinará como sigue: En las esquinas o lugares donde haya señal gráfica de ALTO, los conductores deberán detener completamente sus vehículos. Esto es, antes de las zonas de peatones marcadas o a seis metros antes de la esquina en caso de que no estén marcadas; antes de iniciar la marcha de sus vehículos, los conductores deberán ceder el paso a los peatones que estén cruzando o hayan iniciado el cruce de una calle o avenida. Posteriormente, sin invadir el carril de circulación de la calle transversal, deberán cerciorarse de que no se aproxima ningún vehículo con el que se pueda ocasionar algún hecho de tránsito y hasta entonces iniciarán la marcha, evitando detenerse dentro de la intersección;', 12, 15, 'prioridad_paso'),
('Art. 82', 'Cap. III - De los vehículos', 'Los vehículos de emergencia que hagan uso simultáneo de su sirena y torretas de luz roja, azul, blanca o ámbar, tendrán derecho de paso y movimiento sobre los demás vehículos los cuales deberán extremar precauciones. Se exceptúan los que circulen sobre rieles sin tener la obligación de respetar la preferencia o prioridad de paso en los cruceros o intersecciones. Los conductores de los demás vehículos deberán cederles el paso y auxiliarles en el libre movimiento. En el caso de un hecho de tránsito entre 2-dos o más vehículos de emergencia, haciendo uso de sirena y torretas de luz roja, azul, blanca o ámbar, se aplicará este Reglamento en forma normal.', 15, 20, 'emergencia'),
('Art. 83', 'Cap. III - De los vehículos', 'Los conductores de vehículos que inicien la marcha desde un carril o posición de estacionamiento, deberán ceder el paso a los vehículos en movimiento. Los que se encuentren detenidos sobre un carril de circulación, antes de iniciar la marcha deberán ceder el paso a todo vehículo que haya iniciado alguna maniobra de rebase o vuelta sobre ellos o que haya iniciado el cruce de la calle transversal.', 10, 15, 'reglas_circulacion'),
('Art. 84 Fracc. I', 'Cap. III - De los vehículos', 'La circulación en calles o avenidas de doble circulación deberá hacerse como sigue: Cuando haya sólo un carril para cada circulación opuesta, la circulación deberá hacerse por el carril derecho, pudiendo usarse el carril opuesto si éste está libre, para: Rebasar en lugares permitidos; Dar vuelta a la izquierda o en “U” en lugares permitidos; y Cuando el carril derecho, se encuentre parcial o totalmente obstruido. En cualquiera de los 3-tres casos mencionados, se deberá ceder el paso a los vehículos que circulen acorde al sentido de circulación que se invade;', 15, 20, 'reglas_circulacion'),
('Art. 84 Fracc. III', 'Cap. III - De los vehículos', 'La circulación en calles o avenidas de doble circulación deberá hacerse como sigue: Los camiones o autobuses de pasajeros y los vehículos de transporte de carga pesada, deberán hacerlo siempre por el carril de la derecha, a menos que vayan a dar vuelta a la izquierda o a rebasar;', 30, 50, 'reglas_circulacion'),
('Art. 84 Fracc. IV', 'Cap. III - De los vehículos', 'La circulación en calles o avenidas de doble circulación deberá hacerse como sigue: En las avenidas que cuenten con carril central neutro, este deberá de utilizarse para dar vuelta hacia la izquierda y no entorpecer los carriles normales de circulación.', 10, 15, 'reglas_circulacion'),
('Art. 86 Fracc. I', 'Cap. III - De los vehículos', 'En las maniobras de rebase, los conductores deberán acatar lo siguiente: El conductor que va a rebasar debe: Cerciorarse antes de iniciar la maniobra de que ningún vehículo que le siga haya iniciado previamente la misma maniobra de rebase;', 10, 15, 'rebase'),
('Art. 86 Fracc. I', 'Cap. III - De los vehículos', 'En las maniobras de rebase, los conductores deberán acatar lo siguiente: El conductor que va a rebasar debe: Cerciorarse que el carril de circulación opuesta se encuentra libre de vehículos y obstáculos, en una longitud suficiente que permita realizar la maniobra de rebase sin peligro y sin impedir la marcha normal de vehículos que circulen en sentido opuesto;', 15, 20, 'rebase'),
('Art. 86 Fracc. I', 'Cap. III - De los vehículos', 'En las maniobras de rebase, los conductores deberán acatar lo siguiente: El conductor que va a rebasar debe: Anunciar la maniobra de rebase con luces direccionales y en caso necesario con claxon. Por la noche, deberá hacerlo además con cambio de luces;', 10, 15, 'rebase'),
('Art. 87 Fracc. I', 'Cap. III - De los vehículos', 'Se prohíbe rebasar de las siguientes formas: Por el carril de circulación en: curvas horizontales y verticales, vados, túneles, pasos a desnivel, puentes, intersecciones o cruceros, vías de ferrocarril, en zonas escolares, cuando haya una línea central continua en el pavimento y en todo lugar donde la visibilidad esté obstruida o limitada; Esta prohibición tendrá efecto desde 50- cincuenta metros antes de los lugares mencionados. Cuando en el pavimento existan simultáneamente una línea central continua y otra discontinua, la prohibición de rebasar será para aquellos vehículos que circulen sobre el carril donde esté la línea continua;', 15, 20, 'rebase'),
('Art. 87 Fracc. II', 'Cap. III - De los vehículos', 'Se prohíbe rebasar de las siguientes formas: Por el acotamiento;', 15, 20, 'rebase'),
('Art. 87 Fracc. III', 'Cap. III - De los vehículos', 'Se prohíbe rebasar de las siguientes formas: Por el lado derecho en calles o avenidas de doble circulación que tengan solamente un carril para cada sentido de circulación;', 10, 15, 'rebase'),
('Art. 87 Fracc. V', 'Cap. III - De los vehículos', 'Se prohíbe rebasar de las siguientes formas: A los vehículos que se encuentran detenidos cediendo el paso a peatones;', 15, 20, 'rebase'),
('Art. 87 Fracc. IX', 'Cap. III - De los vehículos', 'Se prohíbe rebasar de las siguientes formas: Por el carril central neutro en las avenidas que cuenten con éste.', 10, 15, 'rebase'),
('Art. 89 Fracc. I', 'Cap. III - De los vehículos', 'Los cambios de carril se deberán efectuar de la siguiente manera: Señalar la maniobra con anticipación mediante el uso de las luces direccionales o con la mano;', 5, 10, 'cambios_carril'),
('Art. 89 Fracc. III', 'Cap. III - De los vehículos', 'Los cambios de carril se deberán efectuar de la siguiente manera: En todos los casos el cambio de carril se hará de uno a la vez, transitando por cada uno una distancia considerable antes de pasar al siguiente, nunca se deberá hacer en forma intempestiva;', 5, 10, 'cambios_carril'),
('Art. 90 Fracc. I', 'Cap. III - De los vehículos', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Tomar su carril correspondiente y señalar la maniobra mediante luces direccionales o con la mano desde una distancia de 50- cincuenta metros antes del lugar donde se vaya a voltear. Se permiten vueltas en más de una fila cuando en el lugar así se permita mediante señalamiento.', 10, 15, 'vueltas'),
('Art. 90 Fracc. I', 'Cap. III - De los vehículos', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Durante la maniobra, la velocidad será moderada.', 10, 15, 'vueltas'),
('Art. 90 Fracc. I', 'Cap. III - De los vehículos', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Durante la maniobra se deberá ceder el paso a los peatones que crucen la calle o avenida hacia donde se está efectuando la vuelta.', 10, 15, 'vueltas'),
('Art. 90 Fracc. I', 'Cap. III - De los vehículos', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Utilizar los carriles exclusivos canalizados o marcados para la realización de vueltas o cambio de dirección.', 10, 15, 'vueltas'),
('Art. 90', 'Cap. III - De los vehículos', 'Las vueltas se deberán realizar de la siguiente manera: Para cualquier tipo de vuelta o cambio de dirección: Tomar su carril correspondiente y señalar la maniobra mediante luces direccionales o con la mano desde una distancia de 50- cincuenta metros antes del lugar donde se vaya a voltear. Se permiten vueltas en más de una fila cuando en el lugar así se permita mediante señalamiento. Antes de efectuar la maniobra se deberá reducir gradualmente la velocidad. Durante la maniobra, la velocidad será moderada. Durante la maniobra se deberá ceder el paso a los peatones que crucen la calle o avenida hacia donde se está efectuando la vuelta. Utilizar los carriles exclusivos canalizados o marcados para la realización de vueltas o cambio de dirección. En todos los casos deberá hacerse alto total antes de la zona de peatones marcada, o 6-seis metros antes de la esquina en caso de que no esté marcada, cediendo el paso a los peatones que estén cruzando o inicien el cruce. Las vueltas a la izquierda de una calle de doble circulación a cochera, estacionamiento, o cualquier lugar fuera de crucero o intersección deberán realizarse de la siguiente manera: La aproximación al lugar se hará sobre el carril izquierdo de su sentido de circulación junto al camellón o línea central pintada o imaginaria divisora de carriles; y Antes de entrar al carril de circulación opuesto, deberán ceder el paso a los vehículos que circulen en sentido opuesto, y a los que circulando atrás de ellos los puedan venir rebasando. Las vueltas a la izquierda de una calle de una sola circulación a una calle de doble circulación deberán realizarse de la siguiente manera: La aproximación al crucero o intersección se deberá hacer por el carril de la izquierda, lo más próximo posible a la banqueta, acotamiento o límite de arroyo de circulación; y Al entrar a la calle transversal, deberán hacerlo a la derecha del centro de la misma, a menos que en el lugar existan señales para dar vuelta en más de una fila. Las vueltas a la izquierda en cruceros donde ambas calles sean de una sola circulación deberán realizarse de la siguiente manera: La aproximación se hará sobre el carril de la izquierda, lo más próximo posible a la banqueta, acotamiento o límite de arroyo de circulación; a menos que en el lugar existan señales para dar vuelta en más de una fila; y Al entrar a la calle transversal podrán hacerlo en cualquiera de sus carriles.', 12, 15, 'vueltas'),
('Art. 94', 'Cap. III - De los vehículos', 'El conductor que de vuelta en “U”, en cruceros donde la calle transversal es de doble circulación, además de ceder el paso a los vehículos que circulen en sentido contrario, debe ceder el paso a los vehículos que circulando por la calle transversal estén dando vuelta a la derecha.', 10, 15, 'vueltas'),
('Art. 95 Fracc. I', 'Cap. III - De los vehículos', 'Quedan prohibidas las vueltas en “U” en los casos siguientes: A media cuadra, se exceptúan los casos cuando haya carriles de retorno;', 10, 15, 'vueltas'),
('Art. 95 Fracc. II', 'Cap. III - De los vehículos', 'Quedan prohibidas las vueltas en “U” en los casos siguientes: En puentes, túneles, vados, pasos a desnivel, lomas, curvas horizontales y verticales, zonas escolares y vías de ferrocarril;', 12, 15, 'vueltas'),
('Art. 95 Fracc. IV', 'Cap. III - De los vehículos', 'Quedan prohibidas las vueltas en “U” en los casos siguientes: En cualquier lugar en donde la maniobra no pueda ser realizada sin efectuar reversa;', 10, 15, 'vueltas'),
('Art. 95 Fracc. V', 'Cap. III - De los vehículos', 'Quedan prohibidas las vueltas en “U” en los casos siguientes: En sentido contrario al que tenga la calle transversal;', 10, 15, 'vueltas'),
('Art. 96', 'Cap. III - De los vehículos', 'Se permite circular en reversa solamente para entrar o salir de cajones de estacionamiento o cocheras, siempre y cuando el espacio que se circule no sea mayor a la longitud del vehículo que lo realice y sin atravesar cruceros. En caso de que la circulación hacia delante esté obstruida totalmente, se permitirá circular en reversa el tramo necesario de acuerdo a las circunstancias.', 15, 20, 'reversa'),
('Art. 97', 'Cap. III - De los vehículos', 'Los conductores de vehículos que circulen en reversa deberán ceder el paso y permitir el libre movimiento a aquellos que circulan de frente, con excepción de cuando dos vehículos pretendan entrar simultáneamente a ocupar un cajón de estacionamiento en paralelo. En este caso, la preferencia de movimiento y entrada al cajón de estacionamiento, será del vehículo que circule en reversa. (No ceder el paso al circular en reversa).', 5, 10, 'reversa'),
('Art. 97', 'Cap. III - De los vehículos', 'Los conductores de vehículos que circulen en reversa deberán ceder el paso y permitir el libre movimiento a aquellos que circulan de frente, con excepción de cuando dos vehículos pretendan entrar simultáneamente a ocupar un cajón de estacionamiento en paralelo. En este caso, la preferencia de movimiento y entrada al cajón de estacionamiento, será del vehículo que circule en reversa. (No ceder el paso a vehículo que entra de reversa a estacionamiento).', 10, 15, 'reversa'),
('Art. 98', 'Cap. III - De los vehículos', 'Los conductores de vehículos que circulen en pendientes descendentes demasiado pronunciadas, deberán usar freno de motor además de los frenos de servicio.', 5, 7, 'reglas_circulacion'),
('Art. 99', 'Cap. III - De los vehículos', 'El conductor de un vehículo debe conservar, respecto del que va adelante, la distancia de seguridad que le garantice su detención oportuna, tomando en cuenta la velocidad, el estado de las calles o avenidas, las condiciones climáticas y las del propio vehículo. Los conductores conservarán entre su vehículo y el que les antecede una distancia como sigue: Para los vehículos con peso bruto menor de 3,500-tres mil quinientos kilogramos, la distancia será de 3-tres metros por cada 10-diez kilómetros por hora de velocidad; y Para los vehículos con peso mayor al anterior, la distancia será igual que en la fracción anterior, si la velocidad es menor a 50-cincuenta kilómetros por hora. Si ésta es mayor, la distancia, deberá ser de 5-cinco metros por cada 10-diez kilómetros de velocidad. Cuando las condiciones sean adversas, que limiten la visibilidad o hagan difícil la conducción de vehículos, se deberán aumentar las distancias antes referidas, de acuerdo a las circunstancias.', 10, 15, 'reglas_circulacion'),
('Art. 100', 'Cap. III - De los vehículos', 'Los conductores de vehículos que entren o salgan de cocheras particulares, cajones o espacios de estacionamiento, estacionamientos públicos o privados, áreas privadas, parques o cualquier lugar no destinado para circulación de vehículos deberán ceder el paso al desplazamiento de peatones y circulación de vehículos en movimiento, con excepción de cuando estos últimos circulen en reversa o en sentido contrario a la circulación.', 10, 15, 'reglas_circulacion'),
('Art. 101', 'Cap. III - De los vehículos', 'Los conductores de todo tipo de vehículos en movimiento deberán encender las luces de circulación, las auxiliares y las especiales de acuerdo a lo previsto en el Artículo 24 Fracción III del presente Reglamento, requeridas de éstos a la puesta del sol. También deberán encenderlas cuando las circunstancias les obstruyan o limiten la visibilidad. (Circular con luces apagadas).', 5, 10, 'reglas_circulacion'),
('Art. 101', 'Cap. III - De los vehículos', 'Los conductores de todo tipo de vehículos en movimiento deberán encender las luces de circulación, las auxiliares y las especiales de acuerdo a lo previsto en el Artículo 24 Fracción III del presente Reglamento, requeridas de éstos a la puesta del sol. También deberán encenderlas cuando las circunstancias les obstruyan o limiten la visibilidad. (Circular sin luces delanteras y/o traseras).', 15, 20, 'reglas_circulacion'),
('Art. 102', 'Cap. III - De los vehículos', 'Los conductores deberán realizar el cambio de luz alta a baja a favor de los conductores de vehículos que se les aproximen en sentido opuesto. Así mismo éstos deberán realizarlo cuando se siga a otro vehículo de tal forma que el uso de la luz alta pueda deslumbrar al conductor del vehículo de adelante.', 5, 10, 'reglas_circulacion'),
('Art. 103', 'Cap. III - De los vehículos', 'Queda prohibido el uso de luces direccionales o de emergencia en caso innecesario y hacer uso de las luces altas en zona urbana, cuando el área esté iluminada.', 5, 10, 'reglas_circulacion'),
('Art. 105 Fracc. I', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Alterar, destruir, derribar, cubrir, cambiar de posición o lugar las señales y/o dispositivos para el control de tránsito y vialidad;', 15, 20, 'vias_publicas'),
('Art. 105 Fracc. II', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Colocar señales o dispositivos de tránsito, tales como boyas, bordos, barreras, aplicar pintura en banquetas, calles o demás vías públicas; o separar de alguna forma espacios para estacionar vehículos sin la autorización de la Autoridad Municipal;', 15, 25, 'vias_publicas'),
('Art. 105 Fracc. III', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Colocar anuncios de cualquier tipo cuya disposición de forma, color, luz o símbolos, se haga de tal forma que puedan confundirse con señales de tránsito y vialidad, u obstaculizar la visibilidad de los mismos; así como colocar espejos en inmuebles que provoquen reflejos en los conductores de los vehículos;', 15, 25, 'vias_publicas'),
('Art. 105 Fracc. V', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Instalar, colocar, arrojar o abandonar objetos, tirar basura, lanzar o esparcir botellas, vidrios, clavos, latas o cualquier material o sustancia que pueda ensuciar o causar daños a las vías públicas u obstaculizar el tránsito de peatones y vehículos o causar algún hecho de tránsito; (arrojar materiales en vía pública).', 20, 50, 'vias_publicas'),
('Art. 105 Fracc. V', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Instalar, colocar, arrojar o abandonar objetos, tirar basura, lanzar o esparcir botellas, vidrios, clavos, latas o cualquier material o sustancia que pueda ensuciar o causar daños a las vías públicas u obstaculizar el tránsito de peatones y vehículos o causar algún hecho de tránsito; (tirar basura o líquidos o colocar y abandonar objetos en la vía pública).', 20, 50, 'vias_publicas'),
('Art. 105 Fracc. VI', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Al abrir zanjas o efectuar trabajos en la vía pública sin la autorización de la Autoridad Municipal, se procederá a retirar de la vía pública de los trabajos abanderando el área y asegurar los vehículos, equipo o maquinaria para garantizar e l pago de los daños ocasionados a la vía pública, así como cumplir con la obligación de que soliciten las autorizaciones correspondientes a la Dependencia Municipal competente. Cuando por circunstancias especiales, la Autoridad antes mencionada otorgue un permiso para depositar materiales, hacer zanjas o realizar trabajos en la vía pública, se deberá señalar el lugar en los términos que para este efecto establezca la Autoridad Municipal requiriendo que la empresa que realice trabajos en la vía pública presente proyecto relativo al señalamiento de protección de obra, el cual deberá ser autorizado y supervisado por la propia Autoridad Municipal, requiriendo cuando menos lo siguiente: DE DÍA: Con una barrera metálica canalizadora de tres tableros de 30-treinta centímetros de ancho por 122-ciento veintidós centímetros como mínimo a cada lado del obstáculo o zona de trabajo por donde se aproximen peatones, semovientes o vehículos. DE NOCHE: Con una barrera metálica canalizadora de 3-tres tableros de 30- treinta centímetros de ancho por 122- ciento veintidós centímetros y 2-dos lámparas de celdas atornilladas en cada extremo de la barrera. Estos dispositivos deberán estar visibles a una distancia de, por lo menos, 100-cien metros de donde se efectúen los trabajos y de ser necesario reforzar con trafitambos colocados a cada 5-cinco metros en el sentido del tránsito hasta completar la distancia de visibilidad.', 15, 30, 'vias_publicas'),
('Art. 105 Fracc. VII', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Reparar o dar mantenimiento a vehículos, a menos que se trate de una evidente emergencia; esta disposición deberá ser respetada especialmente frente a los talleres de servicio automotriz de cualquier clase;', 15, 20, 'vias_publicas'),
('Art. 105 Fracc. XI', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Utilizar las vías públicas como lotes para venta de vehículos;', 15, 20, 'vias_publicas'),
('Art. 105 Fracc. XIII', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: El abastecer de gas butano a vehículos en la vía pública;', 100, 200, 'vias_publicas'),
('Art. 105 Fracc. XIV', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: El hacer uso indebido del claxon; en zonas escolares, hospitales, parques, plazas públicas, iglesias y donde exista concentración de personas; (utilizar el claxon de manera prolongada a un ciclista o peatón).', 2, 10, 'ruido'),
('Art. 105 Fracc. XIV', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: El hacer uso indebido del claxon; en zonas escolares, hospitales, parques, plazas públicas, iglesias y donde exista concentración de personas; (hacer uso indebido del claxon).', 3, 5, 'ruido'),
('Art. 105 Fracc. XVII', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: El abandonar vehículos en la vía pública;', 10, 15, 'vias_publicas'),
('Art. 105', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Queda prohibido en las vías públicas lo siguiente: Utilizar la vía pública como área de carga y descarga sin permiso de la Autoridad correspondiente.', 20, 30, 'vias_publicas'),
('Art. 106', 'Cap. IV - Las vías públicas y zonas privadas con acceso al público', 'Para la realización de desfiles, caravanas, manifestaciones, peregrinaciones o cualquier otro tipo de concentración humana de carácter político, religioso, sindical, deportivo, recreativo, conmemorativo, con finalidad lícita los cuales pueden originar conflictos viales, será necesario que sus organizadores den aviso por escrito a la Autoridad Municipal, por lo menos con 10-diez días hábiles antes del inicio de su celebración, a fin de que oportunamente ésta adopte las medidas preventivas e indispensables a la preservación de la seguridad de los participantes y al mismo tiempo se eviten trastornos a la vialidad, haciendo todo lo posible por encontrar, de común acuerdo, la Autoridad Municipal y los organizadores el horario y la vía o espacio público más adecuados a la conservación de la tranquilidad vial, sin menoscabo de los derechos humanos reconocidos por la Constitución Política de los Estados Unidos Mexicanos. En caso de hacer uso de abanderamiento por parte de la Autoridad Municipal, el organizador deberá realizar el pago de derechos correspondientes.', 15, 20, 'reglas_circulacion'),
('Art. 107 Párr. 1º', 'Cap. V - Los conductores y las licencias de conducir', 'Todos los conductores deben obtener y llevar consigo la licencia de conducir vigente, de acuerdo al vehículo o servicio que corresponda. (Conducir sin licencia).', 10, 15, 'licencia_conducir'),
('Art. 107', 'Cap. V - Los conductores y las licencias de conducir', 'Todos los conductores deben obtener y llevar consigo la licencia de conducir vigente, de acuerdo al vehículo o servicio que corresponda. La licencia debe contener lo siguiente: Nombre Completo; Domicilio. - Este deberá corresponder al lugar donde el conductor resida habitualmente; Tipo de Conductor; Fecha de Vigencia y Número; (conducir con licencia no acorde al vehículo o servicio que presta).', 5, 10, 'licencia_conducir'),
('Art. 107', 'Cap. V - Los conductores y las licencias de conducir', 'Todos los conductores deben obtener y llevar consigo la licencia de conducir vigente, de acuerdo al vehículo o servicio que corresponda. La licencia debe contener lo siguiente: Nombre Completo; Fecha de Vigencia y Número; (conducir con licencia vencida).', 10, 15, 'licencia_conducir'),
('Art. 107', 'Cap. V - Los conductores y las licencias de conducir', 'Todos los conductores deben obtener y llevar consigo la licencia de conducir vigente, de acuerdo al vehículo o servicio que corresponda. La licencia debe contener lo siguiente: Nombre Completo; Domicilio. - Este deberá corresponder al lugar donde el conductor resida habitualmente; Tipo de Conductor; Fecha de Vigencia y Número; Tipo de Sangre; Clave Única de Registro de Población (CURP); y Tipo de Alergias. (Proporcionar datos falsos en expedición de licencia).', 20, 30, 'licencia_conducir'),
('Art. 108', 'Cap. V - Los conductores y las licencias de conducir', 'No se permite a ninguna persona trabajar como chofer con licencia de conducir expedida en el extranjero, a menos que el vehículo que se conduzca sea del mismo país donde se expidió la licencia.', 15, 20, 'licencia_conducir'),
('Art. 111', 'Cap. V - Los conductores y las licencias de conducir', 'Los conductores se clasifican en: CHOFER DE VEHÍCULOS DE SERVICIO PÚBLICO FEDERAL: Este deberá tener licencia del tipo indicado en la Ley de Caminos, Puentes y Autotransporte Federal, según sea el tipo de vehículo, de pasajeros o de carga; CHOFER DE VEHÍCULOS DE SERVICIO PÚBLICO LOCAL: Conductor de vehículos de servicio público, particular o industrial de 10-diez o más pasajeros. Conductor de toda clase de vehículos automotores de 4- cuatro o 6- seis ruedas, de servicio público de carga; así mismo toda persona que preste servicio conduciendo vehículos y reciba un salario, aun cuando éstos sean de servicio particular; Estará facultado para conducir vehículos de servicio particular. AUTOMOVILISTA: Conductor de vehículos de servicio particular de pasajeros y vehículos medianos de carga entendiéndose estos últimos como los vehículos que tengan una capacidad de carga de hasta 3,500-tres mil quinientos kilogramos. MOTOCICLISTA: Los conductores de motocicletas; VEHÍCULOS DE TRACCIÓN ANIMAL: Los que conducen este tipo de vehículos; y CICLISTA: Conductores de bicicletas, bicimotos y triciclos. (Conducir con licencia no acorde al vehículo o servicio que presta).', 5, 10, 'licencia_conducir'),
('Art. 120', 'Cap. VI - La protección de los escolares', 'Los conductores de vehículos de transporte escolar que se detengan en la vía pública para efectuar maniobras de ascenso o descenso, deberán poner en funcionamiento las luces intermitentes de advertencia del vehículo, además de las establecidas en el Artículo 24 Fracción III Numeral 2 del presente reglamento.', 15, 20, 'transporte_escolar'),
('Art. 121', 'Cap. VI - La protección de los escolares', 'Es responsabilidad del conductor del vehículo de transporte escolar tomar las debidas precauciones para que se realicen las maniobras de ascenso y descenso de escolares de manera segura.', 20, 30, 'transporte_escolar'),
('Art. 122 Fracc. III', 'Cap. VI - La protección de los escolares', 'Además de las obligaciones y prohibiciones que se establecen para los conductores en los Artículos 49 y 51 de este mismo Reglamento, los conductores estarán obligados a: Al alcanzar un vehículo de transporte escolar detenido para el ascenso y descenso de escolares, todo conductor detendrá su vehículo atrás del transporte escolar.', 15, 20, 'transporte_escolar'),
('Art. 134 Fracc. VI', 'Cap. IX - Las atribuciones de la autoridad municipal', 'Se impedirá la circulación de vehículos y se retirarán de la vía pública: Cuando notoriamente el vehículo sea un riesgo para la seguridad de su propio conductor, peatones y demás conductores;', 5, 15, 'retiro_vehiculos'),
('Art. 134 Fracc. XV', 'Cap. IX - Las atribuciones de la autoridad municipal', 'Se impedirá la circulación de vehículos y se retirarán de la vía pública, y en su caso se remitirán para depósito mediante el servicio de grúa, al verificarse cualquiera de los siguientes supuestos: No mover el vehículo en un hecho de tránsito, cuando el Policía de Tránsito así lo indique;', 50, 100, 'retiro_vehiculos'),
('Art. 135 Fracc. I', 'Cap. IX - Las atribuciones de la autoridad municipal', 'Los vehículos destinados al servicio público de transporte, además de los casos a que se refiere el artículo anterior, serán impedidos de circular y remitidos al lote autorizado por las siguientes causas: Prestar servicios públicos de transporte de pasajeros con itinerario fijo fuera de la ruta autorizada o por hacer base o parada en lugar no autorizado previamente; (estacionarse más de dos vehículos autobuses, ómnibus en paradas o terminales).', 20, 30, 'transporte_publico'),
('Art. 135 Fracc. I', 'Cap. IX - Las atribuciones de la autoridad municipal', 'Los vehículos destinados al servicio público de transporte, además de los casos a que se refiere el artículo anterior, serán impedidos de circular y remitidos al lote autorizado por las siguientes causas: Prestar servicios públicos de transporte de pasajeros con itinerario fijo fuera de la ruta autorizada o por hacer base o parada en lugar no autorizado previamente; (circular fuera de itinerario los vehículos del servicio público de pasajeros).', 30, 50, 'transporte_publico'),
('Art. 137', 'Cap. X - La seguridad', 'Un hecho de tránsito, es consecuencia de la omisión o transgresión a una norma de circulación por un conductor derivado del movimiento de uno o más vehículos, los cuales pueden chocar entre sí o con personas, semovientes u objetos ocasionándose separada o conjuntamente lesiones, pérdida de la vida o daños materiales, y se clasifican en: ALCANCE. – Ocurre entre 2-dos vehículos que circulan uno delante de otro, en el mismo carril o con la misma trayectoria y el de atrás impacta al de adelante, ya sea que este último vaya en circulación o se detenga normal o repentinamente; CHOQUE DE CRUCERO. – Ocurre entre 2-dos o más vehículos provenientes de arroyos de circulación que convergen o se cruzan, invadiendo un vehículo parcial o totalmente el arroyo de circulación de otro; CHOQUE DE FRENTE. - Ocurre entre 2-dos o más vehículos provenientes de arroyos de circulación opuestos, los cuales chocan cuando uno de ellos invade (n) parcial o totalmente el carril, arroyo de circulación o trayectoria contraria; CHOQUE LATERAL. - Ocurre entre 2- dos o más vehículos cuyos conductores circulan en carriles o con trayectorias paralelas, en el mismo sentido chocando los vehículos entre sí, cuando uno de ellos invada parcial o totalmente el carril o trayectoria donde circula el otro; SALIDA DE LA SUPERFICIE DE RODAMIENTO. Ocurre cuando un conductor pierde el control de su vehículo y se sale de la calle, avenida o carretera; ESTRELLAMIENTO. Ocurre cuando un vehículo en movimiento en cualquier sentido choca con algo que se encuentra provisional o permanentemente estático; VOLCADURA. Ocurre cuando un vehículo pierde completamente el contacto entre llantas y superficie de rodamiento originándose giros verticales o transversales; PROYECCIÓN. Ocurre cuando un vehículo en movimiento choca con o pasa sobre alguien o algo o lo suelta y lo proyecta contra alguien o algo, la proyección puede ser de tal forma que lo proyectado caiga en el carril o trayectoria de otro vehículo y se origine otro hecho de tránsito; ATROPELLO. Ocurre cuando un vehículo en movimiento impacta con una persona. La persona puede estar estática o en movimiento ya sea caminando, corriendo o montando en patines, patinetas, o cualquier juguete similar, o trasladándose asistiéndose de aparatos o de vehículos no regulados por este reglamento, esto en el caso de las personas con discapacidad; CAÍDA DE PERSONA. Ocurre cuando una persona cae hacia fuera o dentro de un vehículo en movimiento; CHOQUE CON MÓVIL DE VEHÍCULO. - Ocurre cuando alguna parte de un vehículo en movimiento o estacionado es abierto, sale, desprende o cae de éste e impacta con algo estático o en movimiento. En esta clasificación se incluyen aquellos casos en los que se caiga o se desprenda algo y no forme parte del vehículo, también cuando un conductor o pasajero saca alguna parte de su cuerpo y se impacta con alguien o algo; y CHOQUES DIVERSOS. En esta clasificación queda cualquier hecho de tránsito no especificado en los puntos anteriores. (Ser responsable en un hecho de tránsito).', 15, 20, 'hechos_transito'),
('Art. 140 Fracc. I', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: No mover los vehículos de la posición dejada por el hecho de tránsito.', 10, 15, 'hechos_transito'),
('Art. 140 Fracc. II', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Prestar o solicitar ayuda para lesionados;', 15, 30, 'hechos_transito'),
('Art. 140 Fracc. IV', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Dar aviso inmediato, o a través de terceros a la Dependencia correspondiente;', 10, 15, 'hechos_transito'),
('Art. 140 Fracc. V', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Proteger el lugar del hecho de tránsito, abanderando de acuerdo a lo establecido en el presente Reglamento;', 10, 20, 'hechos_transito'),
('Art. 140 Fracc. VI', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Esperar en el lugar del hecho de tránsito la intervención del personal de la dependencia competente, a menos que el conductor resulte con lesiones que requieran atención médica inmediata, en cuyo caso deberá notificarles en forma inmediata su localización y esperarlos en el lugar en que le fue prestada la atención médica; (no esperar intervención de Policía de Tránsito en caso de hecho de tránsito).', 10, 15, 'hechos_transito'),
('Art. 140 Fracc. VI', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Esperar en el lugar del hecho de tránsito la intervención del personal de la dependencia competente, a menos que el conductor resulte con lesiones que requieran atención médica inmediata, en cuyo caso deberá notificarles en forma inmediata su localización y esperarlos en el lugar en que le fue prestada la atención médica; (huir en caso de hecho de transito).', 50, 200, 'hechos_transito'),
('Art. 140 Fracc. VII', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Dar al personal de la Dependencia correspondiente la información que le sea solicitada y llenar la hoja de reporte de hecho de tránsito que se les proporcione y también someterse a examen médico cuando se les requiera. (Negarse a llenar parte del hecho de transito).', 10, 15, 'hechos_transito'),
('Art. 140 Fracc. VII', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Dar al personal de la Dependencia correspondiente la información que le sea solicitada y llenar la hoja de reporte de hecho de tránsito que se les proporcione y también someterse a examen médico cuando se les requiera. (Negarse a dar datos y/o a entregar la licencia de conducir y tarjeta de circulación al Policía de Tránsito).', 10, 15, 'hechos_transito'),
('Art. 140 Fracc. VII', 'Cap. X - La seguridad', 'Todo conductor participante en un hecho de tránsito, debe cumplir con lo siguiente: Dar al personal de la Dependencia correspondiente la información que le sea solicitada y llenar la hoja de reporte de hecho de tránsito que se les proporcione y también someterse a examen médico cuando se les requiera. (Proporcionar datos falsos al personal de transito).', 20, 30, 'hechos_transito'),
('Art. 145', 'Cap. X - La seguridad', 'Es obligación de las instituciones médicas públicas o privadas y de profesionistas de la medicina, el dar aviso a la Autoridad Municipal y a las Autoridades correspondientes de cualquier lesionado que reciban para su atención si las lesiones fueron causadas en hechos de tránsito; debiendo además emitir en forma inmediata dictamen médico del lesionado en donde se haga constar lo siguiente: Nombre y domicilio del lesionado; Día y hora en que lo recibió; Quien lo trasladó; Lesiones que presenta; Determinar si presenta estado de ebriedad completo o estado de ebriedad incompleto, e influjo de drogas o estupefacientes; Determinar si las lesiones ponen en peligro la vida, si tardan más o menos de 15- quince días en sanar, la incapacidad parcial o total que se derive y las cicatrices o secuelas permanentes; y Nombre, domicilio, número de cédula profesional y firma de quien atendió al lesionado.', 15, 20, 'hechos_transito'),
('Art. 146', 'Cap. X - La seguridad', 'Todos los vehículos de motor que circulen dentro del Municipio deben estar asegurados por lo menos contra daños a terceros en sus bienes y/o personas con póliza vigente expedida por una Compañía de Seguros autorizada por la Comisión Nacional de Seguros y Fianzas.', 20, 25, 'seguro_vehicular'),
('Art. 149', 'Cap. XI - Las señales y dispositivos para el control y verificación de tránsito', 'Es obligación de todo usuario de la vía pública y privada con acceso al público, respetar fielmente todo lo indicado mediante señales y dispositivos.', 10, 15, 'senales_viales'),
('Art. 150 Fracc. I', 'Cap. XI - Las señales y dispositivos para el control y verificación de tránsito', 'Para los efectos de este Reglamento las señales y dispositivos para el control y verificación del tránsito serán: SEÑALES HUMANAS: Las que deben hacer los conductores para anunciar un cambio de movimiento o dirección de sus vehículos. Esto es, cuando por alguna causa no funcionen las luces de freno o las direccionales; o que el vehículo no esté equipado con dichos dispositivos:', 3, 5, 'senales_viales'),
('Art. 150 Fracc. I', 'Cap. XI - Las señales y dispositivos para el control y verificación de tránsito', 'Para los efectos de este Reglamento las señales y dispositivos para el control y verificación del tránsito serán: SEÑALES HUMANAS: ALTO O REDUCCIÓN DE VELOCIDAD. - Sacarán su brazo izquierdo, colocándolo verticalmente hacia abajo y con la palma de la mano hacia atrás, juntando los dedos. VUELTA A LA DERECHA. - Sacarán su brazo izquierdo y formando un ángulo recto con el antebrazo, empuñarán su mano y con el dedo índice apuntarán hacia arriba. VUELTA A LA IZQUIERDA. - Extenderán horizontalmente su brazo izquierdo, con el puño cerrado y el dedo índice apuntando hacia la izquierda. ESTACIONARSE.- Sacarán su brazo izquierdo extendido hacia abajo, con el puño cerrado y el dedo índice apuntando hacia abajo y harán un movimiento oscilatorio de adelante hacia atrás y viceversa.', 5, 10, 'senales_viales'),
('Art. 150 Fracc. II', 'Cap. XI - Las señales y dispositivos para el control y verificación de tránsito', 'Para los efectos de este Reglamento las señales y dispositivos para el control y verificación del tránsito serán: SEÑALES GRÁFICAS VERTICALES: Las que se encuentran en lámina o en cualquier otro material y se colocan en perfiles o postes, sobre el piso y en las paredes de casas, edificios, puentes o lugares similares. RESTRICTIVAS. - Son aquellas que tienen por objeto indicar limitaciones o prohibiciones que regulan la circulación. Dichas señales tendrán fondo de color blanco con símbolos, leyendas y ribete en colores negro y/o rojo; su forma es cuadrada o rectangular, con excepción de las señales de ALTO Y CEDA EL PASO. La presentación de la primera será en forma octagonal, con fondo de color rojo y las leyendas y ribete en color blanco. La segunda será presentada en forma triangular, debiendo colocarse sobre un vértice. Se utilizarán, el color blanco en el fondo, rojo en el ribete y negro en la leyenda.', 15, 20, 'senales_viales'),
('Art. 152 Fracc. III', 'Cap. XI - Las señales y dispositivos para el control y verificación de tránsito', 'Cuando la circulación esté regulada por medio de semáforos, las indicaciones de éstos tendrán el significado siguiente: ALTO: LUZ ROJA FIJA Y SOLA. - Los conductores deberán detener sus vehículos antes de cruzar la zona de peatones pintada; precisando que la vuelta continua a la derecha está permitida con precaución, excepto cuando exista un señalamiento que expresamente lo prohíba, en cuyo caso deberá cederse en todo momento el paso a los peatones que estén cruzando y a los vehículos que transiten por la vía a la que se pretende incorporar. LUZ ROJA INTERMITENTE. – Los conductores deberán de detener sus vehículos y podrán continuar la marcha después de ceder el paso a los peatones y vehículos que se aproximen por la calle transversal. FLECHA ROJA. - Los conductores de vehículos que pretendan circular en el sentido que indica la flecha, deberán detenerse antes de la zona de peatones hasta que una flecha verde les indique seguir. Al no existir la flecha en luz roja y no estar iluminada la flecha en luz verde, se considerará alto al sentido de la circulación que indique la flecha.', 15, 30, 'semaforos'),
('Art. 166 Fracc. I', 'Cap. XIV - Las infracciones y sanciones', 'Las sanciones por faltas o violaciones al presente Reglamento, consistirán en: SUSPENSIÓN DE LA LICENCIA DE CONDUCIR. - Se suspenderá la licencia de conducir hasta por 3-tres meses y en caso de reincidencia, se suspenderá hasta por 18-dieciocho meses, en los siguientes casos: Por conducir en estado de ebriedad completo o estado de ebriedad incompleto, o bajo el influjo de drogas o sustancias tóxicas; TRATAMIENTO PSICOLÓGICO Y ARRESTO ADMINISTRATIVO Por conducir en alguna de las referidas condiciones en el inciso b), por más de 2- dos veces en un lapso de 2-dos años, deberá asistir y acreditar el tratamiento o curso de rehabilitación, suspensión de la vigencia de la licencia, por doce meses, además de arresto administrativo de 24- veinticuatro a 36-treinta y seis horas, o servicio comunitario. (Conducir en estado de ebriedad incompleta o en estado de ebriedad completa en forma reincidente).', 200, 600, 'sanciones_descuentos'),
('Art. 170 Fracc. IX', 'Cap. XIV - Las infracciones y sanciones', 'Si la infracción es pagada dentro de los 15-quince días naturales contados a partir de la fecha de la infracción se tendrá derecho a un 50-cincuenta por ciento de descuento.', 50, 100, 'sanciones_descuentos')
